using namespace tigersheets;
void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
void cachedNumber(const QString& path,double expected){const auto package=readWorkbook(path.toStdString());pugi::xml_document doc;require(doc.load_string(package.entries.at("xl/worksheets/sheet1.xml").c_str()),"read saved native worksheet XML");bool found=false;for(auto row:doc.document_element().child("sheetData").children())for(auto cell:row.children())if(std::string(cell.attribute("r").value())=="B1"){found=true;require(std::string(cell.child("f").text().as_string())=="A1*2","Save retains the formula");require(cell.child("v")&&cell.child("v").text().as_double()==expected,"native Save writes the current calculated formula value for offline readers");}require(found,"saved formula cell is present");}
QByteArray fileBytes(const QString& path){QFile file(path);require(file.open(QIODevice::ReadOnly),"read native file bytes");return file.readAll();}
void replaceMember(const QString& path,const char* name,const std::string& bytes){int error=0;auto* archive=zip_open(path.toUtf8().constData(),0,&error);require(archive,"open native fixture archive");auto* source=zip_source_buffer(archive,bytes.data(),bytes.size(),0);require(source&&zip_file_add(archive,name,source,ZIP_FL_OVERWRITE)>=0&&zip_close(archive)==0,"update native fixture member");}
void unsupported1904Save(const QString& path){
 auto book=WorkbookSession().snapshot();book["sheets"][0]["cells"]=Json::array({{{"row",1},{"col",1},{"input","42"}},{{"row",1},{"col",2},{"input","=A1*2"},{"style",{{"bold",true}}}}});writeWorkbookCalculated(path.toStdString(),book,CalculationEngine().calculate(book));
 const auto original=readWorkbook(path.toStdString());pugi::xml_document document;require(document.load_string(original.entries.at("xl/workbook.xml").c_str()),"read fixture workbook properties");auto properties=document.document_element().child("workbookPr");if(!properties)properties=document.document_element().prepend_child("workbookPr");properties.append_attribute("date1904")=true;std::ostringstream serialized;document.save(serialized);replaceMember(path,"xl/workbook.xml",serialized.str());
 const auto before=fileBytes(path);MainWindow window;require(window.openWorkbook(path),window.lastError().toUtf8().constData());require(window.currentSession().snapshotView().at("settings").at("date1904")==true,"native fixture uses unsupported 1904 date system");
 require(window.saveWorkbook(path),"unsupported 1904 calculation must still allow native Save");require(fileBytes(path)==before,"unchanged unsupported workbook Save preserves all original bytes");require(window.statusBar()->currentMessage().contains("without recalculated values"),"fallback Save explains that native values were not recalculated");
 auto* model=dynamic_cast<WorksheetModel*>(window.findChild<QTableView*>("worksheet.grid")->model());require(model->apply(Json::array({{{"type","set_style"},{"sheet",model->sheetId().toStdString()},{"row",1},{"col",2},{"style",{{"bold",false}}}}})),"style-only change to unsupported workbook");require(window.saveWorkbook(path),"unsupported workbook style edits remain savable");cachedNumber(path,84);const auto saved=readWorkbook(path.toStdString());require(saved.workbook.at("settings").at("date1904")==true,"fallback retains native date system");require(saved.workbook.at("sheets")[0].at("cells")[1].at("style").value("bold",false)==false,"fallback retains new native cell formatting");
}
void viewOnlySaveAndReopen(const QString& path){
 auto book=WorkbookSession().snapshot();auto second=book["sheets"][0];second["id"]="view-second";second["name"]="Second";book["sheets"].push_back(second);book["settings"]["date1904"]=true;writeWorkbook(path.toStdString(),book);
 MainWindow window;window.resize(1280,720);window.show();QApplication::processEvents();require(window.openWorkbook(path),"open original workbook without saved views");QApplication::processEvents();const auto original=fileBytes(path);require(window.saveWorkbook(path)&&fileBytes(path)==original,"opening and saving a displayed workbook adds no implicit view defaults");
 auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* tabs=window.findChild<QTabBar*>("workspace.sheets");auto* zoom=window.findChild<QSlider*>("worksheet.zoom");const auto before=window.currentSession().snapshot();const bool undo=window.currentSession().canUndo();QTest::mouseClick(tabs,Qt::LeftButton,Qt::NoModifier,tabs->tabRect(1).center());grid->setCurrentIndex(grid->model()->index(50,4));grid->selectionModel()->select(QItemSelection(grid->model()->index(50,4),grid->model()->index(52,6)),QItemSelectionModel::ClearAndSelect);zoom->setValue(125);grid->verticalScrollBar()->setValue(grid->verticalHeader()->sectionPosition(36));grid->horizontalScrollBar()->setValue(grid->horizontalScrollMode()==QAbstractItemView::ScrollPerItem?1:grid->horizontalHeader()->sectionPosition(1));QApplication::processEvents();
 require(window.saveWorkbook(path),"view-only navigation saves without supported recalculation");const auto saved=readWorkbook(path.toStdString()).workbook;require(saved.value("activeSheetIndex",-1)==1&&saved["sheets"][1].value("nativeView",Json::object())==Json({{"activeCell","E51"},{"selection","E51:G53"},{"topLeftCell","B37"},{"zoomScale",125}}),"intentional sheet, selection, scroll and zoom changes persist as real native XLSX views");require(!saved["sheets"][0].contains("nativeView")&&window.currentSession().snapshot()==before&&window.currentSession().canUndo()==undo,"visiting an unchanged first sheet adds no view defaults, cell mutations or undo history");
 require(window.openWorkbook(path),"reopen view-only workbook");QApplication::processEvents();require(tabs->currentIndex()==1&&grid->currentIndex()==grid->model()->index(50,4)&&zoom->value()==125&&grid->rowAt(0)==36&&grid->columnAt(0)==1,"native XLSX reopens its actual active cell and viewport");const auto selected=grid->selectionModel()->selection();require(selected.size()==1&&selected.front()==QItemSelectionRange(grid->model()->index(50,4),grid->model()->index(52,6)),"native XLSX reopens the entire saved selection");const auto reopened=fileBytes(path);require(window.saveWorkbook(path)&&fileBytes(path)==reopened,"unchanged Save preserves bytes when native views already exist");
 QTest::mouseClick(tabs,Qt::LeftButton,Qt::NoModifier,tabs->tabRect(0).center());bool confirmed=false;QTimer::singleShot(0,&window,[&]{if(auto* dialog=qobject_cast<QMessageBox*>(QApplication::activeModalWidget())){confirmed=true;QTest::mouseClick(dialog->button(QMessageBox::Yes),Qt::LeftButton);}});require(window.executeCommand("sheet.delete")&&confirmed,"delete the preceding sheet through its actual native confirmation");require(window.saveWorkbook(path),"saving the surviving loaded active sheet rebases its native tab index");const auto reduced=readWorkbook(path.toStdString()).workbook;require(reduced.at("sheets").size()==1&&reduced.value("activeSheetIndex",-1)==0&&reduced.at("sheets")[0].at("name")=="Second","saved active tab follows worksheet identity after deleting a preceding sheet");require(window.executeCommand("undo")&&window.currentSession().snapshotView().at("sheets").size()==2&&window.saveWorkbook(path),"one Undo restores both worksheet structure and savable active-tab metadata");
}
void calculatedSave(const QString& path){MainWindow window;auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=grid->model();require(model->setData(model->index(0,0),"42",Qt::EditRole)&&model->setData(model->index(0,1),"=A1*2",Qt::EditRole),"enter formula without waiting for background calculation");require(window.saveWorkbook(path),window.lastError().toUtf8().constData());cachedNumber(path,84);require(model->setData(model->index(0,0),"50",Qt::EditRole),"change input immediately before save");require(window.saveWorkbook(path),window.lastError().toUtf8().constData());cachedNumber(path,100);}
void calculationExceptionCannotSavePreviousValues(const QString& path){
 MainWindow window;auto* model=dynamic_cast<WorksheetModel*>(window.findChild<QTableView*>("worksheet.grid")->model());require(model->setData(model->index(0,0),"42",Qt::EditRole)&&model->setData(model->index(0,1),"=A1*2",Qt::EditRole),"create a previous successful calculation");window.recalculateNow();require(model->numericValue(0,1)==84,"previous cached value is observable");
 // Public session replacement intentionally retains a revision to isolate the
 // failure from ordinary edit-revision rejection. Malformed link metadata is
 // accepted by the core, but throws during synchronous link preparation.
 auto replacement=window.currentSession().snapshot();replacement["sheets"][0]["cells"][0]["input"]="50";replacement["links"]=Json::array({{{"name","Broken.xlsx"},{"path","Broken.xlsx"},{"enabled","invalid"}}});window.currentSession()=WorkbookSession(replacement);require(model->numericValue(0,1)==84,"same-revision fixture retains the prior displayed cache before recalculation");
 require(window.saveWorkbook(path),"a calculation exception still allows native preservation Save");require(!model->numericValue(0,1).has_value()&&model->data(model->index(0,1)).toString()!="84"&&!model->copyRange(0,1,0,1).at("cells")[0][0].contains("value"),"failed synchronous calculation clears numeric display and clipboard caches at the same revision");const auto saved=readWorkbook(path.toStdString());pugi::xml_document document;require(document.load_string(saved.entries.at("xl/worksheets/sheet1.xml").c_str()),"read exception fallback worksheet");for(auto row:document.document_element().child("sheetData").children())for(auto cell:row.children())if(std::string(cell.attribute("r").value())=="B1")require(!cell.child("v"),"failed synchronous calculation must not export eligible previous-revision values as current caches");require(window.statusBar()->currentMessage().contains("without recalculated values")&&window.statusBar()->currentMessage().contains("type_error"),"fallback keeps the calculation exception visible");
}
void nonconvergentSave(const QString& path){
 MainWindow window;auto book=window.currentSession().snapshot();book["settings"]={{"iterationEnabled",true},{"maxIterations",3},{"maxChange",0}};book["sheets"][0]["cells"]=Json::array({{{"row",1},{"col",1},{"input","=A1+1"}}});window.currentSession()=WorkbookSession(book);auto* model=dynamic_cast<WorksheetModel*>(window.findChild<QTableView*>("worksheet.grid")->model());model->setSheetId({});require(CalculationEngine().calculate(book).at("status")=="not_converged","fixture genuinely fails to converge");require(window.saveWorkbook(path),"nonconvergent workbook remains savable");const auto saved=readWorkbook(path.toStdString());require(saved.workbook.at("sheets")[0].at("cells")[0].at("input")=="=A1+1","nonconvergent native Save preserves the formula");pugi::xml_document document;require(document.load_string(saved.entries.at("xl/worksheets/sheet1.xml").c_str()),"read divergent native worksheet");require(!document.document_element().child("sheetData").child("row").child("c").child("v"),"nonconvergent Save does not publish provisional values");require(window.statusBar()->currentMessage().contains("without recalculated values"),"nonconvergent save notice stays visible");
}
int main(int argc,char** argv){QApplication app(argc,argv);QTemporaryDir state,files;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{if(argc>1&&std::string(argv[1])=="unsupported1904")unsupported1904Save(files.filePath("unsupported1904.xlsx"));else if(argc>1&&std::string(argv[1])=="views")viewOnlySaveAndReopen(files.filePath("views.xlsx"));else if(argc>1&&std::string(argv[1])=="exception")calculationExceptionCannotSavePreviousValues(files.filePath("exception.xlsx"));else{calculatedSave(files.filePath("calculated.xlsx"));viewOnlySaveAndReopen(files.filePath("views.xlsx"));unsupported1904Save(files.filePath("unsupported1904.xlsx"));calculationExceptionCannotSavePreviousValues(files.filePath("exception.xlsx"));nonconvergentSave(files.filePath("divergent.xlsx"));}std::cout<<"calculated native Save and unsupported-calculation preservation tests passed\n";}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
